def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split pre-release (everything after first '-')
        if '-' in v_without_build:
            core, prerelease = v_without_build.split('-', 1)
        else:
            core = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        # Pre-release versions sort before release versions
        # If prerelease_ids is None, it's a release version (sorts after)
        if prerelease_ids is None:
            return (1,)  # Release versions sort after pre-releases

        # For pre-release, create a tuple for comparison
        # Each identifier is either (0, numeric_value) for all-digit or (1, string_value) for others
        result = [0]  # Pre-release marker (0 sorts before 1)
        for identifier in prerelease_ids:
            if identifier.isdigit():
                result.append((0, int(identifier)))
            else:
                result.append((1, identifier))
        return tuple(result)

    def version_key(v):
        major, minor, patch, prerelease_ids = parse_version(v)
        return (major, minor, patch, prerelease_key(prerelease_ids))

    # Stable sort to preserve input order for equal versions
    return sorted(versions, key=version_key)

